/* Sociales y Ciudadanas · lote 2026-B · tercer cuadernillo («F3»)
 *
 * 46 preguntas (31 a 76), sin superposición con los dos cuadernillos ya
 * cargados (content/sociales-2026b.js): se verificó tema por tema y no hay
 * texto repetido.
 *
 * El cuadernillo NO trae hoja de respuestas. Las claves las determinó el
 * modelo con lectura crítica sobre el propio texto, y por eso se cargan con
 * `clave_origen = 'modelo'`.
 *
 * Errata del original corregida: la pregunta 67 afirma que el fragmento
 * describe "el contexto político de finales de la década de los 1940", pero
 * el propio fragmento cita la muerte de Luis Carlos Galán (asesinado en
 * 1989) y de un magistrado y un coronel de policía — un patrón de violencia
 * narcoterrorista de finales de los 80, no de la Violencia bipartidista de
 * los 40. Se corrigió "1940" por "1980" en el enunciado; la pregunta queda
 * marcada `confianza: 'media'` para que el docente la revise primero.
 *
 * Las explicaciones nunca nombran una letra: las opciones se barajan por
 * estudiante.
 */

const S = (comp, ctxLabel, ctxClass, context, text, opts, correct, exp, tip, confianza) => ({
  comp, ctxLabel: ctxLabel || null, ctxClass: ctxClass || null, context: context || null,
  text, opts, correct, exp, tip, confianza: confianza || 'alta',
});

